SELECT *
FROM document_chunk
WHERE file_id = #{fileId}
  AND tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND public_id = #{chunkPublicId}
FOR UPDATE

SELECT *
FROM document_chunk
WHERE file_id = #{fileId}
  AND tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND position = #{position}

SELECT *
FROM document_chunk
WHERE file_id = #{fileId}
  AND tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND position = #{position}
  AND overlap_enabled = TRUE
FOR UPDATE

mapper.delete:
DELETE FROM document_chunk
WHERE tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND file_id = #{fileId}
  AND public_id = #{chunkPublicId}
  AND status <> 1
  AND lock_version = #{lockVersion}

DELETE FROM document_chunk parent
WHERE parent.id = #{parentId}
  AND parent.tenant_id = #{tenantId}
  AND parent.knowledge_id = #{knowledgeId}
  AND parent.file_id = #{fileId}
  AND parent.chunk_type = 1
  AND NOT EXISTS (
      SELECT 1
      FROM document_chunk child
      WHERE child.parent_chunk_id = parent.id
        AND child.tenant_id = #{tenantId}
        AND child.knowledge_id = #{knowledgeId}
        AND child.file_id = #{fileId}
  )
